      RegistrationQuestionKind('boolean');

  /// Every value this specification's schema permits.
  static const List<RegistrationQuestionKind> values =
      <RegistrationQuestionKind>[text, choice, boolean];
}

/// A question a registrant answers when registering. Answers are read by the event's
/// hosts only, and are deleted on the event's retention schedule (VTI-EVT-034,
/// VTI-EVT-090).
class RegistrationQuestion {
  const RegistrationQuestion({
    required this.questionId,
    required this.label,
    required this.kind,
    this.choices,
    this.required,
  });

  /// Read this payload from a decoded JSON object.
  factory RegistrationQuestion.fromJson(Map<String, dynamic> json) =>
      RegistrationQuestion(
        questionId: json['questionId'] as String,
        label: json['label'] as String,
        kind: RegistrationQuestionKind(json['kind'] as String),
        choices: json['choices'] == null
            ? null
            : (json['choices'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        required: json['required'] as bool?,
      );

  final RegistrationQuestionId questionId;

  /// The question as shown. Plain text.
  final String label;
  final RegistrationQuestionKind kind;

  /// Present exactly when `kind` is `choice`.
  final List<String>? choices;

  /// The registration is refused without an answer. Absent means false.
  final bool? required;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'questionId': questionId,
        'label': label,
        'kind': kind.value,
        if (choices != null) 'choices': choices!,
        if (required != null) 'required': required!,
      };
}

/// One kind of meeting a page offers (VTI-BKG-010).
class BookingMeetingType {
  const BookingMeetingType({
    required this.meetingTypeId,
    required this.title,
    this.description,
    required this.lengthMinutes,
    this.place,
    this.questions,
    this.bufferBeforeMinutes,
    this.bufferAfterMinutes,
    this.minimumNoticeMinutes,
    this.horizonDays,
    this.dailyCap,
    required this.tiers,
  });

  /// Read this payload from a decoded JSON object.
  factory BookingMeetingType.fromJson(Map<String, dynamic> json) =>
      BookingMeetingType(
        meetingTypeId: json['meetingTypeId'] as String,
        title: json['title'] as String,
        description: json['description'] as String?,
        lengthMinutes: json['lengthMinutes'] as int,
        place: json['place'],
        questions: json['questions'] == null
            ? null
            : (json['questions'] as List<dynamic>)
                .map((e) =>
                    RegistrationQuestion.fromJson(e as Map<String, dynamic>))
                .toList(),
        bufferBeforeMinutes: json['bufferBeforeMinutes'] as int?,
        bufferAfterMinutes: json['bufferAfterMinutes'] as int?,
        minimumNoticeMinutes: json['minimumNoticeMinutes'] as int?,
        horizonDays: json['horizonDays'] as int?,
        dailyCap: json['dailyCap'] as int?,
        tiers: (json['tiers'] as List<dynamic>)
            .map((e) => BookingTierRule.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  final BookingMeetingTypeId meetingTypeId;
  final EventTitle title;
  final EventDescription? description;

  /// The meeting's length.
  final int lengthMinutes;

  /// Where it happens; released only to the parties of an accepted booking
  /// (VTI-EVT-060). Shown to the host only on the page.
  final Object? place;

  /// Questions a booker answers; read by the host only (VTI-BKG-011).
  final List<RegistrationQuestion>? questions;

  /// Kept free before each booking.
  final int? bufferBeforeMinutes;

  /// Kept free after each booking.
  final int? bufferAfterMinutes;

  /// The least notice for a booking. Absent: 0.
  final int? minimumNoticeMinutes;

  /// Nothing is offered further ahead. Absent: 60.
  final int? horizonDays;

  /// The most bookings of this type on one local day.
  final int? dailyCap;

  /// One rule per tier that may book it.
  final List<BookingTierRule> tiers;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'meetingTypeId': meetingTypeId,
        'title': title,
        if (description != null) 'description': description!,
        'lengthMinutes': lengthMinutes,
        if (place != null) 'place': place!,
        if (questions != null)
          'questions': questions!.map((e) => e.toJson()).toList(),
        if (bufferBeforeMinutes != null)
          'bufferBeforeMinutes': bufferBeforeMinutes!,
        if (bufferAfterMinutes != null)
          'bufferAfterMinutes': bufferAfterMinutes!,
        if (minimumNoticeMinutes != null)
          'minimumNoticeMinutes': minimumNoticeMinutes!,
        if (horizonDays != null) 'horizonDays': horizonDays!,
        if (dailyCap != null) 'dailyCap': dailyCap!,
        'tiers': tiers.map((e) => e.toJson()).toList(),
      };
}

/// Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url
/// characters. Random, scoped to one community, and stable for the life of the
/// membership — it survives a rotation of the member's DID, which is why groups, notes
/// and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any
/// DID of the member, and the same person's entries in two communities MUST NOT share
/// one. Compared by exact string equality.
typedef EntryId = String;

/// A booking page as the caller may see it (VTI-BKG-001). A booker sees the meeting
/// types their tier may book, without places, buffers' reasons or other tiers' rules;
/// the host sees all of it.
class BookingPage {
  const BookingPage({
    required this.pageId,
    required this.host,
    required this.title,
    this.description,
    required this.availability,
    required this.meetingTypes,
    this.link,
    this.busySuppliedAt,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory BookingPage.fromJson(Map<String, dynamic> json) => BookingPage(
        pageId: json['pageId'] as String,
        host: json['host'] as String,
        title: json['title'] as String,
        description: json['description'] as String?,
        availability: BookingAvailability.fromJson(
            json['availability'] as Map<String, dynamic>),
        meetingTypes: (json['meetingTypes'] as List<dynamic>)
            .map((e) => BookingMeetingType.fromJson(e as Map<String, dynamic>))
            .toList(),
        link: json['link'] as String?,
        busySuppliedAt: json['busySuppliedAt'] as String?,
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
      );

  final BookingPageId pageId;

  /// The host's directory entry.
  final EntryId host;
  final EventTitle title;
  final EventDescription? description;
  final BookingAvailability availability;

  /// The meeting types offered.
  final List<BookingMeetingType> meetingTypes;

  /// The page's link (VTI-BKG-004), an `https` trigger link.
  final String? link;

  /// Host only: when the host's agent last supplied busy time.
  final EventInstant? busySuppliedAt;
  final EventInstant createdAt;
  final EventInstant updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'pageId': pageId,
        'host': host,
        'title': title,
        if (description != null) 'description': description!,
        'availability': availability.toJson(),
        'meetingTypes': meetingTypes.map((e) => e.toJson()).toList(),
        if (link != null) 'link': link!,
        if (busySuppliedAt != null) 'busySuppliedAt': busySuppliedAt!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}

/// A free slot: an instant it starts and one it ends.
class BookingSlot {
  const BookingSlot({
    required this.start,
    required this.end,
  });

  /// Read this payload from a decoded JSON object.
  factory BookingSlot.fromJson(Map<String, dynamic> json) => BookingSlot(
        start: json['start'] as String,
        end: json['end'] as String,
      );

  final EventInstant start;
  final EventInstant end;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'start': start,
        'end': end,
      };
}

/// One busy interval the host's agent supplies: merged, starting and ending on a
/// quarter hour, nothing else (VTI-CAL-061, VTI-BKG-040).
class BookingBusyInterval {
  const BookingBusyInterval({
    required this.start,
    required this.end,
  });

  /// Read this payload from a decoded JSON object.
  factory BookingBusyInterval.fromJson(Map<String, dynamic> json) =>
      BookingBusyInterval(
        start: json['start'] as String,
        end: json['end'] as String,
      );

  final EventInstant start;
  final EventInstant end;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'start': start,
        'end': end,
      };
}

/// Opaque identifier of an event: `evt_` followed by 16 to 64 base64url characters.
/// Random, community-scoped, never reused (VTI-EVT-001).
typedef EventId = String;

/// Where a registration stands (VTI-EVT-032). `going`: has a place. `maybe`: has said
/// maybe; holds no place. `pending`: awaits a host's decision. `waitlisted`: waits for
/// a place, in order. `withdrawn`: the registrant withdrew. `declined`: a host
/// declined a pending registration. `removed`: a host removed it.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RegistrationStatus(String value) {
  static const RegistrationStatus going = RegistrationStatus('going');
  static const RegistrationStatus maybe = RegistrationStatus('maybe');
  static const RegistrationStatus pending = RegistrationStatus('pending');
  static const RegistrationStatus waitlisted = RegistrationStatus('waitlisted');
  static const RegistrationStatus withdrawn = RegistrationStatus('withdrawn');
  static const RegistrationStatus declined = RegistrationStatus('declined');
  static const RegistrationStatus removed = RegistrationStatus('removed');

  /// Every value this specification's schema permits.
  static const List<RegistrationStatus> values = <RegistrationStatus>[
    going,
    maybe,
    pending,
    waitlisted,
    withdrawn,
    declined,
    removed
  ];
}

/// An answer to a question: a string for `text` and `choice`, a boolean for `boolean`.
typedef RegistrationAnswer = Object?;

/// Answers keyed by `questionId`.
typedef RegistrationAnswers = Map<String, RegistrationAnswer>;

/// One booking (VTI-BKG-050): the slot, the tier the booker proved, and the event it
/// is. The booker and the host read it; `answers` the host only.
class Booking {
  const Booking({
    required this.bookingId,
    required this.pageId,
    required this.meetingTypeId,
    required this.eventId,
    required this.start,
    required this.end,
    required this.tier,
    required this.status,
    this.bookerEntryId,
    this.bookerDid,
    this.answers,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory Booking.fromJson(Map<String, dynamic> json) => Booking(
        bookingId: json['bookingId'] as String,
        pageId: json['pageId'] as String,
        meetingTypeId: json['meetingTypeId'] as String,
        eventId: json['eventId'] as String,
        start: json['start'] as String,
        end: json['end'] as String,
        tier: BookingTier(json['tier'] as String),
        status: RegistrationStatus(json['status'] as String),
        bookerEntryId: json['bookerEntryId'] as String?,
        bookerDid: json['bookerDid'] as String?,
        answers: json['answers'],
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
      );

  final BookingId bookingId;
  final BookingPageId pageId;
  final BookingMeetingTypeId meetingTypeId;
  final EventId eventId;
  final EventInstant start;
  final EventInstant end;
  final BookingTier tier;
  final RegistrationStatus status;

  /// A member booker's directory entry. Exactly one of this and `bookerDid`.
  final EntryId? bookerEntryId;

  /// A booker who is not a member, by their identifier.
  final String? bookerDid;

  /// The host's view only.
  final Object? answers;
  final EventInstant createdAt;
  final EventInstant updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'bookingId': bookingId,
        'pageId': pageId,
        'meetingTypeId': meetingTypeId,
        'eventId': eventId,
        'start': start,
        'end': end,
        'tier': tier.value,
        'status': status.value,
        if (bookerEntryId != null) 'bookerEntryId': bookerEntryId!,
        if (bookerDid != null) 'bookerDid': bookerDid!,
        if (answers != null) 'answers': answers!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}
